import Foundation

/// Troubleshooting: "why is X not working". Each entry names the likeliest causes and the exact setting or screen to check. Four of them are backed by a live check Setu can run
/// (diag.playback, diag.guide, diag.source, diag.engine); the rest are explained from what the app does, and point at real controls.
enum AtlasDiagnoses {
    private static func d(_ id: String, _ title: String, _ summary: String, path: [String], aliases: [String], detail: String? = nil, related: [String] = [], platforms: AtlasPlatforms = .all, reviewed: Bool = false) -> AtlasEntry {
        AtlasEntry.make(id, .diagnosis, title, summary, path: path, reach: AtlasReach.none, aliases: aliases, detail: detail, platforms: platforms, related: related, safety: .read, reviewed: reviewed)
    }

    static let all: [AtlasEntry] = [
        // The four with a live check
        d("diag.playback", "Why a stream will not play or keeps buffering",
          "The usual causes are the network, the provider, a rejected login, a format the player cannot open, or a device that cannot keep up. Try Try again, then another player engine, then a bigger buffer.",
          path: ["Troubleshooting", "Playback"],
          aliases: ["not playing", "wont play", "keeps buffering", "buffering", "stutters", "freezes", "lagging", "channel not working", "stream fails", "error when playing", "keeps stopping", "playback problem", "why is this buffering"],
          detail: "Check Settings, Playback, Player engine, and Buffering mode (Large buffer helps a poor connection, Low latency suits live TV on a fast one). If the picture glitches, set Hardware decoding to Software decoding. A VPN or proxy can slow streams. Setu can check this for you: ask while the stream is playing and it reads the player's state.",
          related: ["setting.enginePreference", "setting.bufferingMode", "setting.hardwareDecoding", "diag.engine", "diag.source"], reviewed: true),
        d("diag.guide", "Why the TV guide is empty or the times are wrong",
          "The guide comes from each playlist's XMLTV address. It is empty when the playlist has no guide address, nothing has been downloaded yet, or the provider returned nothing; channels still play without it.",
          path: ["Troubleshooting", "TV Guide"],
          aliases: ["guide is empty", "epg empty", "no programme info", "guide times wrong", "guide hours off", "programmes missing", "tv guide blank", "guide out of date", "few channels have a guide"],
          detail: "Run Refresh Guide (Settings, Library, Programme guide). If times are hours off, use Guide time shift for that playlist (Playlists, its Guide section). If only a few channels have entries, the provider's channel ids do not match the playlist's, which only the provider can fix. Setu can check this for you and says which of these it found.",
          related: ["setting.guideShift", "setting.guideRefresh", "setting.guideRetentionDays", "setting.catchupClock"], reviewed: true),
        d("diag.source", "Why a playlist will not load or its login is rejected",
          "A playlist that is switched off is not refreshed. Otherwise the server name cannot be found (a DNS filter or a typo), the network cannot reach it, the server is slow or down, or it rejects the username and password.",
          path: ["Troubleshooting", "Playlists"],
          aliases: ["playlist wont load", "provider not working", "login rejected", "401", "403", "authorization failed", "password expired", "too many devices", "server not found", "source not loading", "refresh failed", "provider down"],
          detail: "A rejected login usually means the password is wrong or expired, or the account is already streaming on too many devices. Check them with your provider and update them in the playlist's settings. If the name cannot be found, check the address and try App DNS. Setu can check this for you: it asks the server whether it answers, and never sends your login.",
          related: ["setting.appDNS", "setting.userAgent", "setting.subscriptions", "diag.channelsEmpty"], reviewed: true),
        d("diag.engine", "Which player engine to use",
          "Apple's player is best for HLS and MP4. MPV opens MKV, raw MPEG-TS, RTSP and DASH, and has more audio and picture options. Automatic picks for each stream and tries the other engine once if a format fails.",
          path: ["Troubleshooting", "Player engine"],
          aliases: ["avplayer or mpv", "mpv or avplayer", "which engine", "best engine for this stream", "switch engine", "codec not supported", "mkv wont play", "format not supported"],
          detail: "Settings, Playback, Player engine sets it for everything; a playlist or channel can have its own choice. Setu can check this for you: it looks at the stream's format and says which engine suits it.",
          related: ["setting.enginePreference", "setting.engineForKind", "setting.playlistEngine", "diag.playback", "diag.noPipAirplay"], reviewed: true),

        // Playback symptoms
        d("diag.noSound", "Why there is no sound",
          "Check that the player is not muted and the volume is up, then the audio track, the output device, and Downmix to stereo.",
          path: ["Troubleshooting", "Sound"],
          aliases: ["no sound", "no audio", "silent video", "sound missing", "cant hear anything", "wrong language audio", "audio too quiet", "only one speaker"],
          detail: "A stream can carry several audio tracks: switch tracks in the player. On a Mac, Settings, Playback, Audio, Output device decides where the sound goes (System default follows macOS). Downmix to stereo mixes 5.1 and 7.1 down to two channels. Preferred language picks the track automatically. If a stream has video but never any sound, try the other player engine.",
          related: ["setting.audioOutputUID", "setting.stereoDownmix", "setting.preferredAudioLanguage", "setting.audioProcessing", "setting.enginePreference"], reviewed: true),
        d("diag.blackScreen", "Why the picture is black or frozen",
          "A black picture with sound is usually a decoding problem or a format the chosen engine handles badly. Try Software decoding, then the other player engine.",
          path: ["Troubleshooting", "Picture"],
          aliases: ["black screen", "no picture", "no video", "video is green", "picture frozen", "audio but no video", "blank screen", "artifacts", "glitchy picture"],
          detail: "Settings, Playback, Video, Hardware decoding set to Software decoding avoids hardware quirks on some streams (it applies to MPV). Settings, Playback, Player engine lets you switch engine. If the stream does not start at all, it is more likely a provider or network problem.",
          related: ["setting.hardwareDecoding", "setting.enginePreference", "setting.renderingProfile", "diag.playback"], reviewed: true),
        d("diag.hdrWashed", "Why HDR video looks dull or washed out",
          "HDR shown on a normal display needs tone mapping. Automatic is best unless colours look wrong; then try another method.",
          path: ["Troubleshooting", "Picture"],
          aliases: ["hdr looks washed out", "hdr dull", "colours look grey", "hdr too dark", "colours wrong"],
          detail: "Settings, Playback, Advanced video, HDR tone mapping offers BT.2390, Hable, Mobius, Reinhard and Clip. It applies from the next stream and needs the MPV engine. Picture adjustments can also be reset there.",
          related: ["setting.toneMapping", "setting.picture", "setting.enginePreference"], platforms: .mac, reviewed: true),
        d("diag.liveBehind", "Why live TV is behind real time",
          "On Apple's player the buffering mode sets how far behind the live edge you stay: about 3 seconds for Low latency, 10 for Standard and 24 for Large buffer. The provider's own delay adds to that.",
          path: ["Troubleshooting", "Live TV"],
          aliases: ["live tv is behind", "delay on live channel", "goal comes late", "live is lagging", "spoilers from phone", "stream delayed", "make live faster"],
          detail: "Set Settings, Playback, Buffering, Mode to Low latency (live) for the least delay, at the cost of more stalls on a poor connection. A playlist can use its own mode under Playlists, Connection.",
          related: ["setting.bufferingMode", "setting.playlistBuffering", "setting.liveRewind"], reviewed: true),
        d("diag.subtitlesMissing", "Why subtitles do not show",
          "Show subtitles by default only turns them on when a track in your language exists. Otherwise pick a track with the player's subtitle button, or fetch one online.",
          path: ["Troubleshooting", "Subtitles"],
          aliases: ["subtitles not showing", "no subtitles", "subtitles missing", "captions not working", "subs wont turn on", "subtitle button greyed", "no subtitle track"],
          detail: "Check Preferred language (Settings, Playback, Subtitles) and Show by default. Fetch automatically gets one from OpenSubtitles when none exists, but needs your own free OpenSubtitles account and API key (Subtitles online). Subtitle size, colour and background are in the same group.",
          related: ["setting.subtitlesByDefault", "setting.preferredSubtitleLanguage", "setting.autoSubtitles", "setting.opensubtitlesKey", "setting.subtitleSize"], reviewed: true),
        d("diag.subtitlesOutOfSync", "Why subtitles or sound are out of sync",
          "A subtitle file made for another copy of the film runs early or late. The player has a timing control for subtitles and one for sound, which need the MPV engine.",
          path: ["Troubleshooting", "Subtitles"],
          aliases: ["subtitles out of sync", "subtitles too early", "subtitles too late", "lip sync", "audio out of sync", "sound delay", "subtitle delay", "captions lag"],
          detail: "Open the player's subtitle or audio menu and change the delay: on iPhone and iPad these are Subtitle timing and Sound sync. If the whole subtitle file is wrong, choose another subtitle track or fetch another one.",
          related: ["setting.autoSubtitles", "setting.enginePreference", "diag.subtitlesMissing"], reviewed: true),

        // Library and artwork
        d("diag.artwork", "Why posters are missing or wrong",
          "Posters, summaries, years and ratings your playlist lacks are matched from TMDB in the background, on Wi-Fi, using the title and year. A wrong poster is usually a wrong match on a similar title.",
          path: ["Troubleshooting", "Artwork"],
          aliases: ["posters are wrong", "wrong artwork", "missing posters", "no poster", "wrong picture for movie", "artwork not loading", "no logos", "wrong cover"],
          detail: "Settings, Library, Artwork and details: check Match artwork in the background is on, press Match now, and allow mobile data or hotspots if you are not on Wi-Fi. You can use your own free TMDB key. Clear artwork cache (Settings, Advanced, Reset) makes posters download again.",
          related: ["setting.tmdb", "setting.artworkBackground", "setting.tmdbKey", "setting.maintenance"], reviewed: true),
        d("diag.castSearch", "Why a search by actor finds nothing",
          "A film is only found by its cast after the app has read its cast. It reads slowly in the background, never while something plays.",
          path: ["Troubleshooting", "Search"],
          aliases: ["actor search not working", "cant find movies by actor", "director search empty", "cast not found", "actor has no movies", "search by cast"],
          detail: "Settings, Library, Cast and directors shows how many movies have been read. Read Cast Now speeds it up, four at a time. A TMDB key also lets the app look up an actor's full filmography.",
          related: ["setting.castReading", "setting.tmdb"], reviewed: true),
        d("diag.searchEmpty", "Why search finds nothing",
          "Check the spelling, that the playlist is switched on and has refreshed, and that the title is not in a locked folder, which is missing from every list and search until unlocked.",
          path: ["Troubleshooting", "Search"],
          aliases: ["search finds nothing", "search not working", "no results", "cant find a movie i know i have", "search is empty", "search index"],
          detail: "If everything looks right, Settings, Library, Maintenance (turn on Show maintenance tools) lets you verify and rebuild the search index; your channels, movies, series, favorites and history are not touched. Searching by actor needs the cast to have been read.",
          related: ["setting.maintenance", "setting.parentalPin", "diag.castSearch", "diag.channelsEmpty"], reviewed: true),
        d("diag.channelsEmpty", "Why a playlist shows no channels",
          "The playlist may be switched off, its last refresh may have failed, or its folders may be hidden: empty folders when Hide empty folders is on, or locked folders.",
          path: ["Troubleshooting", "Playlists"],
          aliases: ["channel list empty", "no channels after refresh", "playlist is empty", "folders are missing", "categories disappeared", "movies missing after refresh", "restored playlist is off"],
          detail: "Check Settings, Library, Manage, Playlists: the playlist must be on, and its Health section shows the last refresh. A playlist restored from a backup comes back switched off and asks for its login. Settings, Library, Catalog shows the current state and Refresh All Playlists.",
          related: ["setting.hideEmptyFolders", "setting.catalogRefresh", "diag.source", "diag.lockedHidden"], reviewed: true),
        d("diag.continueEmpty", "Why Continue Watching is empty",
          "A title appears once you have watched more than 30 seconds and not finished it. Remember playback position must be on, and each profile has its own list.",
          path: ["Troubleshooting", "Continue Watching"],
          aliases: ["continue watching is empty", "resume not working", "it forgot where i stopped", "no resume point", "continue watching missing", "history is empty"],
          detail: "Settings, Playback, Behaviour: with Remember playback position off, no resume points are written. A title you removed with Remove from Continue Watching stays out until you play it again. Watch Privately never saves anything. Live channels have no position. Series show once, on the newest episode.",
          related: ["setting.rememberPosition", "setting.resumeAutomatically", "diag.profileFavourites"], reviewed: true),
        d("diag.profileFavourites", "Why favourites or history are missing",
          "Each profile has its own favourites, collections, watch history and resume points, so another profile is probably active.",
          path: ["Troubleshooting", "Profiles"],
          aliases: ["favourites disappeared", "favorites missing", "history gone", "where did my watch later go", "someone else is using my list", "collections missing", "wrong profile"],
          detail: "Switch profile from the account menu. Settings, Library, Profiles lists them. If you use more than one device, iCloud sync or Sync on this network moves favourites, Watch Later, collections and resume points between devices.",
          related: ["setting.profiles", "setting.icloudSync", "setting.lanSync"], reviewed: true),
        d("diag.lockedHidden", "Why a folder or title has disappeared (locked folders)",
          "A folder locked behind the parental PIN is missing from every list and search until you unlock it with the PIN. It locks again by itself after the Unlock lasts time.",
          path: ["Troubleshooting", "Parental controls"],
          aliases: ["folder disappeared", "locked folder hidden", "adult channels gone", "pin locked", "cant see a category", "unlock restricted content", "forgot pin", "kids profile hides channels"],
          detail: "Use Unlock in Settings, Privacy, Parental controls, Unlock restricted content in the account menu, or the PIN box where a locked folder is shown. A kids profile keeps locked folders hidden and needs its PIN to leave. App lock is a separate thing: it asks for Touch ID or the Mac password when the app opens. Setu never sees or changes the PIN.",
          related: ["setting.parental", "setting.parentalPin", "setting.parentalUnlock", "setting.appLock", "setting.profiles"], reviewed: true),

        // Sync, downloads, recordings, network
        d("diag.sync", "Why sync between devices is not working",
          "iCloud sync needs the same Apple ID on every device and the switch on each. Sync on this network needs the devices on the same Wi-Fi and paired once.",
          path: ["Troubleshooting", "Sync"],
          aliases: ["icloud sync not working", "favourites not syncing", "devices not syncing", "iphone and mac not matching", "lan sync not finding my phone", "pairing fails", "sync stuck"],
          detail: "Settings, Library, iCloud shows a Status row, anything Waiting to send, and Sync Now. Sync logins is separate and needs iCloud sync on. Both iCloud sync and Sync on this network are choices about each device, so they are not synced themselves. For network sync, Add a Device on both and check the list says On this network.",
          related: ["setting.icloudSync", "setting.syncLogins", "setting.lanSync"], reviewed: true),
        d("diag.downloads", "Why a download will not start or has paused",
          "A download pauses while something is playing. On iPhone and iPad it also waits for Wi-Fi unless Only on Wi-Fi is turned off.",
          path: ["Troubleshooting", "Downloads"],
          aliases: ["download wont start", "download stuck", "download paused", "downloads wont work on mobile data", "download failed", "cant download movie"],
          detail: "Downloads are kept on the device and out of backups; they can be removed at any time from Settings, Library, Downloads (Mac) or the Downloads screen (iPhone and iPad). The source still has to be reachable when the download starts.",
          related: ["setting.downloads", "setting.downloadsWifiOnly", "setting.downloadsDeleteWatched", "diag.source"], reviewed: true),
        d("diag.recording", "Why a recording fails or did not happen",
          "Recording uses the MPV engine and the connection you are already watching with. A scheduled recording opens its own connection to the provider, and the app has to be open at that time.",
          path: ["Troubleshooting", "Recordings"],
          aliases: ["recording failed", "recording did not start", "scheduled recording missed", "cant record", "recording is empty", "dvr not working"],
          detail: "Recordings are live channels only. Settings, Library, Recordings lists them with the reason a scheduled one failed or was missed. A provider that allows one stream at a time may refuse a second connection; Subscriptions shows how many streams the account allows. The Mac stays awake while recording.",
          related: ["setting.recordings", "setting.scheduledRecordings", "setting.subscriptions", "setting.enginePreference"], platforms: .mac, reviewed: true),
        d("diag.vpnPause", "Why playback stops when a VPN drops",
          "Pause if the VPN drops pauses playback on purpose when a connected VPN is lost, so streams do not carry on over your normal connection.",
          path: ["Troubleshooting", "VPN"],
          aliases: ["streams stop when my vpn drops", "playback pauses by itself", "vpn kill switch", "stops when vpn reconnects", "pauses after vpn blip"],
          detail: "It only acts while something is playing, and only for a VPN the app can detect. Turn it off in Settings, Privacy, VPN. StreamSetu does not run the VPN and cannot see what it does. Setu cannot change this setting.",
          related: ["setting.vpn", "setting.proxy", "setting.appDNS"], reviewed: true),
        d("diag.noPipAirplay", "Why Picture in Picture or AirPlay is not available",
          "The MPV engine cannot do Picture in Picture or AirPlay; Apple's player can. If the stream is playing in MPV, switch it to Apple's player.",
          path: ["Troubleshooting", "Player engine"],
          aliases: ["picture in picture not working", "pip greyed out", "airplay not available", "cant cast to apple tv", "no airplay button", "pip missing"],
          detail: "Automatic uses MPV for MKV, raw MPEG-TS, RTSP and DASH, which Apple's player cannot open, so those streams cannot use either. Pick Apple AVPlayer for the playlist or app (Settings, Playback, Player engine) for streams it can open.",
          related: ["setting.enginePreference", "setting.playlistEngine", "diag.engine"], reviewed: true),
        d("diag.reminders", "Why programme reminders do not appear",
          "Reminders are local notifications. Programme reminders must be on, and the system must allow notifications for StreamSetu.",
          path: ["Troubleshooting", "Reminders"],
          aliases: ["reminders not working", "no notification before a show", "bell does nothing", "notifications denied", "guide alert did not fire"],
          detail: "Settings, General, Notifications shows the macOS permission and opens System Settings, Notifications when it was denied. Reminders fire a minute before the programme starts. Guide alerts also need Programme reminders on.",
          related: ["setting.remindersEnabled", "setting.notificationPermission", "setting.keywordAlerts"], reviewed: true),
    ]
}
